// MarioWalk.cpp sWeightTable and sinking branch; caller supplies original state inputs.
inline std::array<float,4> nativeMarioWalkTargets(unsigned index,unsigned sinkTimer=0){
 assetCheck(index<8,"Invalid Mario walk speed index");
 static constexpr std::array<std::array<float,4>,8> table{{{0,0,0,1},{1,0,0,0},{.75f,.25f,0,0},{.25f,.75f,0,0},{0,1,0,0},{0,.75f,.25f,0},{0,.25f,.75f,0},{0,0,1,0}}};
 if(!sinkTimer)return table[index];std::array<float,4> result{};if(index==0)result[3]=1;else if(index<=3){float weight=index==2?.75f:index==3?.5f:1;result[0]=weight;result[1]=1-weight;}else{float weight=index>=5?std::min(1.f,float(sinkTimer)/100):1;result[1]=weight;result[2]=1-weight;}return result;
}
inline void marioWalkTargetTests(){for(unsigned index=0;index<8;++index)for(unsigned timer:{0u,1u,25u,100u,150u}){auto weights=nativeMarioWalkTargets(index,timer);float sum=0;for(float weight:weights){assetCheck(weight>=0&&weight<=1,"Invalid walk target component");sum+=weight;}assetCheck(sum==1,"Walk targets not normalized");}assetCheck(nativeMarioWalkTargets(3,1)[0]==.5f&&nativeMarioWalkTargets(5,25)[1]==.25f&&nativeMarioWalkTargets(7,150)[1]==1,"Sinking walk target branches mismatch");bool rejected=false;try{nativeMarioWalkTargets(8);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Invalid walk index accepted");}

// Mario::decideWalkSpeed hysteresis and state caps; vibration/smoothing side effects pending.
inline unsigned nativeMarioWalkIndex(float magnitude,unsigned previous,unsigned clingCount=0,bool underwater=false,bool beeWall=false,bool floor32=false){assetCheck(std::isfinite(magnitude)&&magnitude>=0&&magnitude<=1&&previous<8,"Invalid Mario walk index input");constexpr float rising[]={.15f,.3f,.45f,.6f,.7f,.85f,.99f};constexpr float falling[]={.02f,.2f,.4f,.5f,.65f,.75f,.98f};bool decrease=previous!=0&&magnitude<falling[previous-1];unsigned index=0;while(index<7&&magnitude>=rising[index])++index;unsigned result=previous<=index||decrease?index:previous;if(clingCount)result=std::min(result,5-std::min(clingCount,5u));if(underwater)result=std::min(result,6u);if(beeWall)result=std::min(result,4u);if(floor32)result=std::min(result,3u);return result;}
inline void marioWalkIndexTests(){assetCheck(nativeMarioWalkIndex(.15f,0)==1&&nativeMarioWalkIndex(.99f,0)==7,"Walk index rising boundary mismatch");assetCheck(nativeMarioWalkIndex(.21f,2)==2&&nativeMarioWalkIndex(.19f,2)==1,"Walk index hysteresis mismatch");assetCheck(nativeMarioWalkIndex(1,7,10)==0&&nativeMarioWalkIndex(1,7,0,true)==6&&nativeMarioWalkIndex(1,7,0,false,true)==4&&nativeMarioWalkIndex(1,7,0,false,false,true)==3,"Walk state caps mismatch");bool rejected=false;try{nativeMarioWalkIndex(-1,0);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Invalid walk magnitude accepted");}

// Base cadence from MarioWalk.cpp; slope/spin/sink modifiers are separate and pending.
inline float nativeMarioBaseWalkRate(unsigned index,float walkSpeed,float speedConstant,bool beeWall=false){assetCheck(std::isfinite(walkSpeed)&&walkSpeed>=0&&std::isfinite(speedConstant)&&speedConstant>=0,"Invalid Mario walking cadence input");auto weights=nativeMarioWalkTargets(index);constexpr float normal[]={1.2f,1.5f,1.3f,0};constexpr float bee[]={.5f,.5f,.5f,0};float stride=0;for(size_t i=0;i<4;++i)stride+=(beeWall?bee[i]:normal[i])*weights[i];float rate=stride==0?.33f:.5f*(60*(.01f*(walkSpeed*speedConstant)/stride));assetCheck(std::isfinite(rate)&&rate<=4096,"Mario walking cadence overflow");return rate;}
inline void marioWalkRateTests(){assetCheck(nativeMarioBaseWalkRate(0,0,13)==.33f,"Idle cadence fallback mismatch");float full=nativeMarioBaseWalkRate(7,1,13);assetCheck(std::abs(full-3)<1e-5f&&std::abs(nativeMarioBaseWalkRate(7,.5f,13)-full*.5f)<1e-5f,"Walking cadence speed scaling mismatch");assetCheck(nativeMarioBaseWalkRate(7,1,13,true)>full,"Bee stride cadence mismatch");}

// Final MarioWalk cadence stages: sinking minimum, then attenuation (_2D0).
inline float nativeMarioFinalizeWalkRate(float rate,unsigned index,unsigned sinkTimer,float attenuation){assetCheck(std::isfinite(rate)&&rate>=0&&rate<=4096&&index<8&&std::isfinite(attenuation)&&attenuation>=0&&attenuation<=1,"Invalid Mario final cadence input");if(sinkTimer&&index&&rate<1)rate=1;return rate*(1-attenuation);}
inline void marioWalkFinalRateTests(){assetCheck(nativeMarioFinalizeWalkRate(.25f,1,10,.5f)==.5f,"Sinking cadence clamp order mismatch");assetCheck(nativeMarioFinalizeWalkRate(.25f,0,10,.5f)==.125f,"Idle sinking cadence incorrectly clamped");assetCheck(nativeMarioFinalizeWalkRate(3,7,0,1)==0&&nativeMarioFinalizeWalkRate(3,7,0,0)==3,"Cadence attenuation endpoint mismatch");bool rejected=false;try{nativeMarioFinalizeWalkRate(1,1,0,2);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Invalid cadence attenuation accepted");}

struct NativeMarioSlopeRate {float rate;bool requestSlopeSpin;};
// MarioWalk slope/alternate-state rate branch; effect and clip selection remain caller-owned.
inline NativeMarioSlopeRate nativeMarioSlopeWalkRate(float base,float slope,float slopeRatio,float spinRatio,bool suppressSlope=false,bool alternateState=false,float alternateRatio=1){assetCheck(std::isfinite(base)&&base>=0&&std::isfinite(slope)&&std::isfinite(slopeRatio)&&slopeRatio>=0&&std::isfinite(spinRatio)&&spinRatio>=0&&std::isfinite(alternateRatio)&&alternateRatio>=0,"Invalid Mario slope cadence input");bool spin=false;if(slope>0&&!suppressSlope){base*=1+(slope/10)*slopeRatio;if(slope>5&&base>4){base*=spinRatio;spin=true;}}else if(alternateState)base*=alternateRatio;assetCheck(std::isfinite(base)&&base<=4096,"Mario slope cadence overflow");return {base,spin};}
inline void marioSlopeRateTests(){auto slope=nativeMarioSlopeWalkRate(3,10,1,.5f,false,true,3);assetCheck(slope.rate==3&&slope.requestSlopeSpin,"Slope spin scaling/precedence mismatch");auto boundary=nativeMarioSlopeWalkRate(4,5,0,.5f);assetCheck(boundary.rate==4&&!boundary.requestSlopeSpin,"Slope strict threshold mismatch");auto alternate=nativeMarioSlopeWalkRate(2,10,1,1,true,true,.25f);assetCheck(alternate.rate==.5f&&!alternate.requestSlopeSpin,"Suppressed slope alternate ratio mismatch");bool rejected=false;try{nativeMarioSlopeWalkRate(1,1,-1,1);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Invalid slope cadence ratio accepted");}

struct NativeMarioStartRate {float rate,startBlend;};
// Host sqrt for positive values; original fastSqrtf returns nonpositive input unchanged.
inline float nativeMarioPositiveSqrt(float value){return value>0?std::sqrt(value):value;}
inline NativeMarioStartRate nativeMarioStartWalkRate(float rate,float walkSpeed,float targetSpeed,float speedConstant,float startRatio,bool beeWall=false,bool floor32=false,unsigned index=0){assetCheck(std::isfinite(rate)&&rate>=0&&std::isfinite(walkSpeed)&&walkSpeed>=0&&walkSpeed<=1&&std::isfinite(targetSpeed)&&targetSpeed>=0&&targetSpeed<=1&&std::isfinite(speedConstant)&&speedConstant>=0&&std::isfinite(startRatio)&&startRatio>=0&&index<8,"Invalid Mario start cadence input");float difference=targetSpeed-walkSpeed;if(walkSpeed>.6f){float factor=(walkSpeed-.6f)/.4f;difference=difference*(1-factor)+difference*difference*factor;}else if(walkSpeed<.4f){float factor=(.4f-walkSpeed)/.4f;difference=difference*factor+nativeMarioPositiveSqrt(difference)*(1-factor);}float acceleration=std::max(1.f,std::min(2.f,1+4*difference));if(targetSpeed<.8f)acceleration=1;if(floor32&&index)acceleration=1.2f;float minimum=startRatio*(.5f*(60*((targetSpeed*speedConstant*.01f)/(beeWall?.5f:1.3f))));float factor=2-acceleration;if(rate<minimum)rate=rate*factor+minimum*(1-factor);assetCheck(std::isfinite(rate)&&rate<=4096,"Mario start cadence overflow");return {rate,acceleration-1};}
inline void marioStartRateTests(){assetCheck(nativeMarioPositiveSqrt(-.5f)==-.5f&&nativeMarioPositiveSqrt(0)==0,"Original nonpositive fast-sqrt behavior lost");auto floor=nativeMarioStartWalkRate(1,1,1,13,1,false,true,7);assetCheck(std::abs(floor.rate-1.4f)<1e-5f&&std::abs(floor.startBlend-.2f)<1e-6f,"Floor start cadence interpolation mismatch");auto low=nativeMarioStartWalkRate(1,.2f,.3f,13,1);assetCheck(low.rate==1&&low.startBlend==0,"Low target acceleration suppression mismatch");auto accelerating=nativeMarioStartWalkRate(1,.5f,1,13,1);assetCheck(std::abs(accelerating.rate-3)<1e-5f&&accelerating.startBlend==1,"Start cadence acceleration clamp mismatch");}

struct NativeMarioWalkCadenceContext {
 unsigned index=0,sinkTimer=0;float walkSpeed=0,targetSpeed=0,speedConstant=0,startRatio=0,slope=0,slopeRatio=0,spinRatio=1,alternateRatio=1,attenuation=0;bool beeWall=false,suppressSlope=false,alternateState=false,floor32=false;
};
struct NativeMarioWalkCadence {float rate,startBlend;bool requestSlopeSpin;};
inline NativeMarioWalkCadence nativeMarioWalkCadence(const NativeMarioWalkCadenceContext& context){float base=nativeMarioBaseWalkRate(context.index,context.walkSpeed,context.speedConstant,context.beeWall);auto slope=nativeMarioSlopeWalkRate(base,context.slope,context.slopeRatio,context.spinRatio,context.suppressSlope,context.alternateState,context.alternateRatio);auto start=nativeMarioStartWalkRate(slope.rate,context.walkSpeed,context.targetSpeed,context.speedConstant,context.startRatio,context.beeWall,context.floor32,context.index);return {nativeMarioFinalizeWalkRate(start.rate,context.index,context.sinkTimer,context.attenuation),start.startBlend,slope.requestSlopeSpin};}
inline void marioWalkCadenceTests(){NativeMarioWalkCadenceContext idle;assetCheck(nativeMarioWalkCadence(idle).rate==.33f,"Composed idle cadence mismatch");NativeMarioWalkCadenceContext moving;moving.index=7;moving.walkSpeed=moving.targetSpeed=1;moving.speedConstant=13;moving.startRatio=1;moving.slope=10;moving.slopeRatio=1;moving.spinRatio=.5f;moving.attenuation=.5f;auto result=nativeMarioWalkCadence(moving);assetCheck(std::abs(result.rate-1.5f)<1e-5f&&result.requestSlopeSpin&&result.startBlend==0,"Composed slope/start/attenuation stage order mismatch");moving.slope=0;moving.walkSpeed=.1f;moving.targetSpeed=.1f;moving.sinkTimer=1;moving.attenuation=.5f;assetCheck(std::abs(nativeMarioWalkCadence(moving).rate-.5f)<1e-6f,"Composed sinking cadence order mismatch");}

inline NativeMarioWalkCadenceContext nativeMarioDefaultCadence(){NativeMarioWalkCadenceContext context;context.speedConstant=NativeMarioAnimationDefaults::speedConstant;context.startRatio=NativeMarioAnimationDefaults::startRatio;context.slopeRatio=NativeMarioAnimationDefaults::slopeRatio;context.spinRatio=NativeMarioAnimationDefaults::spinRatio;return context;}
inline void marioDefaultCadenceTests(){auto context=nativeMarioDefaultCadence();assetCheck(context.speedConstant==13&&context.startRatio==1.25f&&context.slopeRatio==.5f&&context.spinRatio==.75f,"Extracted Mario cadence defaults mismatch");context.index=7;context.walkSpeed=context.targetSpeed=1;assetCheck(std::abs(nativeMarioWalkCadence(context).rate-3)<1e-5f,"Original default full-run cadence mismatch");}

// Mario::getTargetWalkSpeed; explicit native state inputs and bounded sink range.
inline float nativeMarioTargetWalkSpeed(unsigned index,unsigned sinkTimer=0,bool blocked=false,unsigned severeFloor=0,float attenuation=0,bool dash=false,float dashRatio=1){assetCheck(index<8&&sinkTimer<=256&&std::isfinite(attenuation)&&attenuation>=0&&attenuation<=1&&std::isfinite(dashRatio)&&dashRatio>=0&&dashRatio<=16,"Invalid Mario target speed context");if(blocked)return 0;constexpr float target[]={0,.15f,.25f,.4f,.5f,.6f,.8f,1};float result=target[index];if(sinkTimer){if(severeFloor==25||severeFloor==31)result=0;else result*=1-float(sinkTimer)/256;}result*=1-attenuation;if(dash)result*=dashRatio;return result;}
inline void marioTargetSpeedTests(){assetCheck(nativeMarioTargetWalkSpeed(7)==1&&nativeMarioTargetWalkSpeed(2)==.25f,"Walk target table mismatch");assetCheck(nativeMarioTargetWalkSpeed(2,128,false,0,.5f,true,2)==.125f,"Walk target modifier order mismatch");assetCheck(nativeMarioTargetWalkSpeed(7,1,false,25)==0&&nativeMarioTargetWalkSpeed(7,1,false,31)==0&&nativeMarioTargetWalkSpeed(7,0,true)==0,"Blocked/severe floor target mismatch");bool rejected=false;try{nativeMarioTargetWalkSpeed(7,257);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Invalid sink timer accepted");}

// Bounded arithmetic from Mario::updateWalkSpeed; caller supplies decided target/inertia.
struct NativeMarioWalkSpeedState {
 float speed=0;unsigned slowRemaining=0;
 void update(float target,float inertia,unsigned slowStart,unsigned sinkTimer=0,bool tornado=false,float tornadoRatio=1){assetCheck(std::isfinite(target)&&target>=0&&target<=16&&std::isfinite(speed)&&speed>=0&&std::isfinite(inertia)&&inertia>=0&&inertia<=1&&slowStart<=600&&slowRemaining<=slowStart&&sinkTimer<=256&&std::isfinite(tornadoRatio)&&tornadoRatio>=0&&tornadoRatio<=16,"Invalid Mario walk speed state");unsigned remaining=target==0?slowStart:slowRemaining;float factor=1;if(remaining){assetCheck(slowStart>0,"Empty slow-start duration");factor=float(slowStart-remaining)/slowStart;--remaining;}target*=factor*factor;if(tornado)target*=tornadoRatio;target*=float(256-sinkTimer)/256;float next=speed*inertia+target*(1-inertia);assetCheck(std::isfinite(next)&&next<=256,"Mario walking speed overflow");speed=next;slowRemaining=remaining;}
};
inline void marioWalkSpeedTests(){NativeMarioWalkSpeedState state;state.slowRemaining=4;state.update(1,0,4);assetCheck(state.speed==0&&state.slowRemaining==3,"Slow-start initial ramp mismatch");state.update(1,0,4);assetCheck(state.speed==.0625f,"Slow-start squared ramp mismatch");state.update(1,0,4);state.update(1,0,4);state.update(1,0,4);assetCheck(state.speed==1&&state.slowRemaining==0,"Slow-start completion mismatch");state.update(1,.5f,4,128,true,.5f);assetCheck(state.speed==.625f,"Walking inertia/tornado/sinking order mismatch");auto before=state;bool rejected=false;try{state.update(1,2,4);}catch(const std::exception&){rejected=true;}assetCheck(rejected&&state.speed==before.speed&&state.slowRemaining==before.slowRemaining,"Invalid walk speed state committed");}

struct NativeMarioInertiaConstants {float standardStop,standardMax,startSpin,stop;};
// Base normal/slip interpolation uses current speed; ice uses clamped target speed.
inline float nativeMarioBaseInertia(float current,float target,float startBlend,const NativeMarioInertiaConstants& constants,bool ice=false){assetCheck(std::isfinite(current)&&current>=0&&current<=1&&std::isfinite(target)&&target>=0&&std::isfinite(startBlend)&&startBlend>=0&&startBlend<=1,"Invalid Mario inertia context");for(float value:{constants.standardStop,constants.standardMax,constants.startSpin,constants.stop})assetCheck(std::isfinite(value)&&value>=0&&value<=1,"Invalid Mario inertia constant");float speed=ice?std::min(target,1.f):current;float inertia=(1-speed)*constants.standardStop+speed*constants.standardMax;inertia=(1-startBlend)*inertia+startBlend*constants.startSpin;if(target==0)inertia=constants.stop;return inertia;}
inline void marioInertiaTests(){NativeMarioInertiaConstants constants{.9f,.8f,.7f,.95f};assetCheck(std::abs(nativeMarioBaseInertia(.5f,1,.5f,constants)-.775f)<1e-6f,"Normal inertia interpolation mismatch");assetCheck(nativeMarioBaseInertia(.1f,2,0,constants,true)==.8f,"Ice target speed clamp mismatch");assetCheck(nativeMarioBaseInertia(.5f,0,1,constants)==.95f,"Stopped inertia override mismatch");bool rejected=false;try{nativeMarioBaseInertia(.5f,1,2,constants);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Invalid inertia blend accepted");}

inline NativeMarioInertiaConstants nativeMarioNormalInertia(){using namespace NativeMarioAnimationDefaults;return {mInertiaStandardStop,mInertiaStandardMax,mInertiaStartSpin,mInertiaStop};}
inline NativeMarioInertiaConstants nativeMarioIceInertia(){using namespace NativeMarioAnimationDefaults;return {mInertiaIceStandardStop,mInertiaIceStandardMax,mInertiaIceStartSpin,mInertiaIceStop};}
inline NativeMarioInertiaConstants nativeMarioSlipInertia(){using namespace NativeMarioAnimationDefaults;return {mInertiaSlipStandardStop,mInertiaSlipStandardMax,mInertiaSlipStartSpin,mInertiaSlipStop};}
inline void marioDefaultInertiaTests(){assetCheck(std::abs(nativeMarioBaseInertia(.5f,1,0,nativeMarioNormalInertia())-.92f)<1e-6f,"Original normal inertia defaults mismatch");assetCheck(nativeMarioBaseInertia(0,0,0,nativeMarioIceInertia(),true)==.992f&&nativeMarioBaseInertia(0,0,0,nativeMarioSlipInertia())==.98f,"Original ice/slip defaults mismatch");NativeMarioWalkSpeedState speed;speed.update(1,nativeMarioBaseInertia(0,1,0,nativeMarioNormalInertia()),0);assetCheck(std::abs(speed.speed-.06f)<1e-6f,"Original default inertia speed update mismatch");}

struct NativeMarioStopInertiaContext {bool turnSlip=false,turning=false,squat=false;unsigned jumpFinishSteps=30;};
struct NativeMarioStopInertiaConstants {float stop,turnSlip,turning,jumpFinish,squat;};
inline float nativeMarioStopInertia(const NativeMarioStopInertiaContext& context,const NativeMarioStopInertiaConstants& constants){for(float value:{constants.stop,constants.turnSlip,constants.turning,constants.jumpFinish,constants.squat})assetCheck(std::isfinite(value)&&value>=0&&value<=1,"Invalid Mario stop inertia constant");float result=constants.stop;if(context.turnSlip)result=constants.turnSlip;if(context.turning)result=constants.turning;if(context.jumpFinishSteps<30)result=constants.jumpFinish;if(context.squat)result=constants.squat;return result;}
inline void marioStopInertiaTests(){NativeMarioStopInertiaConstants constants{.8f,.7f,.6f,.5f,.4f};NativeMarioStopInertiaContext state;assetCheck(nativeMarioStopInertia(state,constants)==.8f,"Default stop inertia mismatch");state.turnSlip=true;state.turning=true;assetCheck(nativeMarioStopInertia(state,constants)==.6f,"Turning stop inertia precedence mismatch");state.jumpFinishSteps=29;assetCheck(nativeMarioStopInertia(state,constants)==.5f,"Jump finish stop inertia precedence mismatch");state.squat=true;assetCheck(nativeMarioStopInertia(state,constants)==.4f,"Squat stop inertia precedence mismatch");state.squat=false;state.jumpFinishSteps=30;assetCheck(nativeMarioStopInertia(state,constants)==.6f,"Jump finish strict boundary mismatch");}

inline NativeMarioStopInertiaConstants nativeMarioDefaultStopInertia(){using namespace NativeMarioAnimationDefaults;return {mInertiaStop,mInertiaTurnSlip,mInertiaTurning,mInertiaJumpFinish,mInertiaSquat};}
inline void marioDefaultStopInertiaTests(){auto constants=nativeMarioDefaultStopInertia();NativeMarioStopInertiaContext state;assetCheck(nativeMarioStopInertia(state,constants)==NativeMarioAnimationDefaults::mInertiaStop,"Extracted stop inertia mismatch");state.squat=true;NativeMarioWalkSpeedState speed;speed.speed=1;speed.update(0,nativeMarioStopInertia(state,constants),0);assetCheck(speed.speed==NativeMarioAnimationDefaults::mInertiaSquat,"Original squat stopping speed mismatch");}

struct NativeMarioSpecialInertiaConstants {float tornadoBrake,tornadoAccel,reflect,startSpin;unsigned startSpinTime;};
struct NativeMarioSpecialInertiaState {
 float walkSpeed=0;unsigned reflectTicks=0,startSpinTicks=0,cooldown=0;
 float update(float inertia,float target,unsigned jumpSteps,bool tornado,bool squat,bool alternate,bool brakeFloor,const NativeMarioSpecialInertiaConstants& constants){assetCheck(std::isfinite(inertia)&&inertia>=0&&inertia<=1&&std::isfinite(target)&&target>=0&&target<=16&&std::isfinite(walkSpeed)&&walkSpeed>=0&&walkSpeed<=16&&reflectTicks<=600&&startSpinTicks<=600&&cooldown<=600&&constants.startSpinTime<=600,"Invalid special inertia state");for(float value:{constants.tornadoBrake,constants.tornadoAccel,constants.reflect,constants.startSpin})assetCheck(std::isfinite(value)&&value>=0&&value<=1,"Invalid special inertia constant");auto next=*this;if(tornado)inertia=next.walkSpeed>=target?constants.tornadoBrake:constants.tornadoAccel;if(next.reflectTicks){--next.reflectTicks;inertia=constants.reflect;}if(next.walkSpeed<.08f&&jumpSteps>10&&target>.5f&&(squat||alternate)){next.startSpinTicks=constants.startSpinTime;next.walkSpeed=.08f;}if(next.startSpinTicks){--next.startSpinTicks;inertia=constants.startSpin;if(!next.startSpinTicks)next.cooldown=60;}if(next.cooldown)--next.cooldown;if(brakeFloor&&next.walkSpeed>.4f)inertia*=.5f;*this=next;return inertia;}
};
inline void marioSpecialInertiaTests(){NativeMarioSpecialInertiaConstants constants{.9f,.8f,.7f,.6f,2};NativeMarioSpecialInertiaState state;state.walkSpeed=.5f;state.reflectTicks=2;assetCheck(state.update(.95f,1,30,true,false,false,true,constants)==.35f&&state.reflectTicks==1,"Reflect/tornado/brake precedence mismatch");state={};assetCheck(state.update(.95f,1,11,false,true,false,false,constants)==.6f&&state.walkSpeed==.08f&&state.startSpinTicks==1,"Start spin activation mismatch");state.update(.95f,1,11,false,true,false,false,constants);assetCheck(state.startSpinTicks==0&&state.cooldown==59,"Start spin completion cooldown mismatch");state={};state.update(.95f,.5f,11,false,true,false,false,constants);assetCheck(state.walkSpeed==0&&state.startSpinTicks==0,"Start spin strict target threshold mismatch");}

inline NativeMarioSpecialInertiaConstants nativeMarioDefaultSpecialInertia(){using namespace NativeMarioAnimationDefaults;return {mInertiaTornadoBrake,mInertiaTornadoAccel,mInertiaReflectSlip,mInertiaStartSpin,startSpinTime};}
inline void marioDefaultSpecialInertiaTests(){auto constants=nativeMarioDefaultSpecialInertia();NativeMarioSpecialInertiaState state;float rate=state.update(.9f,1,11,false,true,false,false,constants);assetCheck(rate==constants.startSpin&&state.walkSpeed==.08f&&state.startSpinTicks+1==constants.startSpinTime,"Original special inertia defaults mismatch");for(unsigned i=1;i<constants.startSpinTime;++i)state.update(.9f,1,11,false,true,false,false,constants);assetCheck(state.startSpinTicks==0&&state.cooldown==59,"Original spin duration completion mismatch");}

struct NativeMarioInertiaContext {float target=0,startBlend=0;bool skate=false,ice=false,slip=false,tornado=false,alternate=false,brakeFloor=false;NativeMarioStopInertiaContext stopping;};
inline float nativeMarioDecideInertia(NativeMarioSpecialInertiaState& state,const NativeMarioInertiaContext& context){assetCheck(std::isfinite(state.walkSpeed)&&state.walkSpeed>=0&&state.walkSpeed<=16&&std::isfinite(context.target)&&context.target>=0&&context.target<=16&&std::isfinite(context.startBlend)&&context.startBlend>=0&&context.startBlend<=1,"Invalid Mario inertia decision context");if(context.skate)return nativeMarioBaseInertia(std::min(state.walkSpeed,1.f),context.target,context.startBlend,nativeMarioIceInertia(),true);if(state.walkSpeed>1)return NativeMarioAnimationDefaults::mInertiaOverSpeed;if(context.ice)return nativeMarioBaseInertia(state.walkSpeed,context.target,context.startBlend,nativeMarioIceInertia(),true);if(context.slip)return nativeMarioBaseInertia(state.walkSpeed,context.target,context.startBlend,nativeMarioSlipInertia());float inertia=nativeMarioBaseInertia(state.walkSpeed,context.target,context.startBlend,nativeMarioNormalInertia());if(context.target==0)inertia=nativeMarioStopInertia(context.stopping,nativeMarioDefaultStopInertia());return state.update(inertia,context.target,context.stopping.jumpFinishSteps,context.tornado,context.stopping.squat,context.alternate,context.brakeFloor,nativeMarioDefaultSpecialInertia());}
inline void marioDecideInertiaTests(){NativeMarioSpecialInertiaState state;state.walkSpeed=1.5f;state.reflectTicks=2;NativeMarioInertiaContext context;context.target=1;context.skate=true;assetCheck(nativeMarioDecideInertia(state,context)==NativeMarioAnimationDefaults::mInertiaIceStandardMax&&state.reflectTicks==2,"Skate early-return precedence mismatch");context.skate=false;context.ice=true;assetCheck(nativeMarioDecideInertia(state,context)==NativeMarioAnimationDefaults::mInertiaOverSpeed&&state.reflectTicks==2,"Overspeed early-return precedence mismatch");state.walkSpeed=.5f;context.ice=false;context.slip=true;nativeMarioDecideInertia(state,context);assetCheck(state.reflectTicks==2,"Slip early-return changed counters");context.slip=false;context.target=0;context.stopping.squat=true;assetCheck(nativeMarioDecideInertia(state,context)==NativeMarioAnimationDefaults::mInertiaReflectSlip&&state.reflectTicks==1,"Normal reflect override sequence mismatch");}
